"use client";

// Every YouTube channel the research studies analysed: how many of its videos were analysed, which ones (with links,
// the study and the strategies each gave), and its other uploads that were not analysed, grouped by why not. The
// reasons for videos not analysed are read from their titles (the Trading Video Lab's channel listings), the way the
// studies chose what to read. Data: ./ytChannelsData.ts, generated by
// backend/research/youtube_channel_index/build_channel_index.mjs. It is about 1 MB, so it loads only when this tab opens.
import { useEffect, useMemo, useState } from "react";
import GlassPanel from "../../components/GlassPanel";
import type { YtChannel, YtListedChannel, YtNot, YtUpload } from "./ytChannelsData";

type Data = {
  meta: { channels: number; videos: number; with_uploads_listed: number; uploads: number; not_analysed: Record<string, number>; listed_not_analysed: number;
    strategies: number; no_rule: number; repeats: number; built: string };
  studies: Record<string, string>; reasons: Record<string, string>; channels: YtChannel[]; listed: YtListedChannel[];
};

const watch = (v: string) => `https://www.youtube.com/watch?v=${v}`;
const channelUrl = (c: { id: string | null; handle: string | null }) =>
  c.handle ? `https://www.youtube.com/${c.handle}` : c.id && /^UC[\w-]{22}$/.test(c.id) ? `https://www.youtube.com/channel/${c.id}` : null;
const num = (n: number | null | undefined) => (n === null || n === undefined ? "–" : n.toLocaleString("en-IN"));
const views = (n: number | null) => (n === null ? "" : n >= 1e6 ? `${(n / 1e6).toFixed(1)}M views` : n >= 1e3 ? `${Math.round(n / 1e3)}K views` : `${n} views`);
const STATUS_LABEL: Record<string, string> = { coded: "coded", blocked: "no testable rule", duplicate: "repeat", analysed: "read" };
const STATUS_TONE: Record<string, string> = { coded: "ok", blocked: "warn", duplicate: "", analysed: "" };

// Dates of videos not analysed come from YouTube's channel listing, which says "5 years ago": they can be months off,
// so only the month is shown, marked "about".
const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const approxDate = (d: string | null) => {
  const m = d ? /^(\d{4})-(\d{2})/.exec(d) : null;
  return m ? `about ${MONTHS[Number(m[2]) - 1]} ${m[1]}` : null;
};

function Upload({ u }: { u: YtUpload }) {
  return (
    <li>
      <a href={watch(u.v)} target="_blank" rel="noopener noreferrer">{u.t || u.v}</a>
      <span className="yc-dim">{[approxDate(u.d), views(u.w), u.q].filter(Boolean).map(s => ` · ${s}`).join("")}</span>
    </li>
  );
}

function NotGroup({ g, reasons }: { g: YtNot; reasons: Record<string, string> }) {
  const more = g.n - g.list.length;
  const note = g.r === "strategy_not_picked" ? "the most viewed are listed" : g.r === "waiting" ? "" : "a few examples, most viewed first";
  return (
    <details className="yc-not">
      <summary>
        <b>{num(g.n)}</b> {reasons[g.r] || g.r}
      </summary>
      <ul className="yc-list">
        {g.list.map(u => <Upload key={u.v} u={u} />)}
      </ul>
      {more > 0 && <div className="yc-dim">{num(more)} more with this reason are not listed here{note ? ` (${note})` : ""}.</div>}
    </details>
  );
}

function Channel({ c, data, open, onToggle }: { c: YtChannel; data: Data; open: boolean; onToggle: (open: boolean) => void }) {
  const url = channelUrl(c);
  const notTotal = c.not.reduce((n, g) => n + g.n, 0);
  return (
    // React passes a nested <details>' toggle up to this one, so read this element's own state and skip the others'.
    <details className="yc-ch" open={open} onToggle={e => { if (e.target === e.currentTarget) onToggle(e.currentTarget.open); }}>
      <summary>
        <span className="yc-name">{c.name}</span>
        <span className="yc-count">{num(c.analysed.length)} analysed{c.uploads !== null ? ` of ${num(c.uploads)} uploads` : ""}</span>
        {c.counts.coded > 0 && <span className="yc-tag ok">{c.counts.coded} coded</span>}
        {c.counts.blocked > 0 && <span className="yc-tag warn">{c.counts.blocked} no testable rule</span>}
        {c.counts.duplicate > 0 && <span className="yc-tag">{c.counts.duplicate} repeats</span>}
        {c.studies.map(s => <span key={s} className="yc-tag">{data.studies[s] || s}</span>)}
      </summary>
      {open && (
        <div className="yc-body">
          <div className="yc-line">
            {url ? <a href={url} target="_blank" rel="noopener noreferrer">Open the channel on YouTube</a> : <span className="yc-dim">Channel link not known</span>}
            {c.listed && <span className="yc-dim"> · uploads listed on {c.listed}</span>}
          </div>
          <h4 className="yc-h">Analysed videos ({c.analysed.length})</h4>
          <table className="yc-table">
            <thead><tr><th>Uploaded</th><th>Video</th><th>Study</th><th>Strategies it gave</th></tr></thead>
            <tbody>
              {c.analysed.map(v => (
                <tr key={v.v}>
                  <td className="yc-nowrap">{v.d || "–"}</td>
                  <td><a href={watch(v.v)} target="_blank" rel="noopener noreferrer">{v.t || v.v}</a>{v.m ? <span className="yc-dim"> · {v.m} min</span> : null}</td>
                  <td className="yc-dim">{v.s.map(s => data.studies[s] || s).join(", ")}</td>
                  <td>{v.x.length ? v.x.map((x, i) => (
                    <span key={`${x.id}-${i}`} className={`yc-tag ${STATUS_TONE[x.st] || ""}`} title={STATUS_LABEL[x.st] || x.st}>{x.id || STATUS_LABEL[x.st] || x.st}</span>
                  )) : <span className="yc-dim">read; no strategy recorded</span>}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <h4 className="yc-h">Not analysed{c.uploads !== null ? ` (${num(notTotal)})` : ""}</h4>
          {c.uploads === null ? (
            <p className="yc-dim">This channel&apos;s uploads were never listed (no channel catalogue in the Trading Video Lab), so its other videos are not shown here.</p>
          ) : c.not.length ? (
            c.not.map(g => <NotGroup key={g.r} g={g} reasons={data.reasons} />)
          ) : (
            <p className="yc-dim">Every listed upload was analysed.</p>
          )}
        </div>
      )}
    </details>
  );
}

export default function YtChannels() {
  const [data, setData] = useState<Data | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [q, setQ] = useState("");
  const [study, setStudy] = useState("");
  const [sort, setSort] = useState<"analysed" | "name" | "uploads" | "untried">("analysed");
  const [opened, setOpened] = useState<Set<string>>(new Set());

  useEffect(() => {
    let live = true;
    import("./ytChannelsData")
      .then(m => { if (live) setData({ meta: m.YT_META, studies: m.YT_STUDIES, reasons: m.YT_REASONS, channels: m.YT_CHANNELS, listed: m.YT_LISTED_NOT_ANALYSED }); })
      .catch(e => { if (live) setError(String(e?.message || e)); });
    return () => { live = false; };
  }, []);

  const shown = useMemo(() => {
    if (!data) return [];
    const text = q.trim().toLowerCase();
    const untried = (c: YtChannel) => c.not.find(g => g.r === "strategy_not_picked")?.n || 0;
    const rows = data.channels.filter(c => (!study || c.studies.includes(study))
      && (!text || c.name.toLowerCase().includes(text) || c.analysed.some(v => v.t.toLowerCase().includes(text) || v.x.some(x => (x.id || "").toLowerCase().includes(text)))));
    return [...rows].sort((a, b) => sort === "name" ? a.name.localeCompare(b.name) : sort === "uploads" ? (b.uploads || 0) - (a.uploads || 0)
      : sort === "untried" ? untried(b) - untried(a) : b.analysed.length - a.analysed.length || a.name.localeCompare(b.name));
  }, [data, q, study, sort]);
  const listedShown = useMemo(() => {
    if (!data) return [];
    const text = q.trim().toLowerCase();
    return text ? data.listed.filter(c => c.name.toLowerCase().includes(text) || c.waiting.some(u => u.t.toLowerCase().includes(text))) : data.listed;
  }, [data, q]);

  if (error) return <GlassPanel title="YouTube channels"><p className="yc-dim">Could not load the channel list: {error}</p></GlassPanel>;
  if (!data) return <GlassPanel title="YouTube channels"><p className="yc-dim">Loading the channel list…</p></GlassPanel>;
  const m = data.meta;
  const key = (c: YtChannel) => c.id || c.name;
  const toggle = (c: YtChannel, open: boolean) => setOpened(prev => { const next = new Set(prev); if (open) next.add(key(c)); else next.delete(key(c)); return next; });

  return (
    <>
      <GlassPanel title={`YouTube channels — ${num(m.channels)} channels analysed`} note={`${num(m.videos)} videos analysed · built ${m.built}`}>
        <p className="yc-intro">
          Every YouTube channel whose videos the research studies have read: the channel shortlist, the 20-channel, 11-channel, top-20
          traders and intraday studies, and the Booming Bulls studies. Each analysed video was read from its transcript. Most gave exact
          strategy rules, some gave no testable rule, and some repeated a strategy already coded. Every title links to the video on YouTube.
          For {num(m.with_uploads_listed)} of these channels the Trading Video Lab also listed every upload ({num(m.uploads)} in all), so the
          videos <b>not</b> analysed are shown too, each with its reason. The studies read the clearest strategy-titled videos first, a few per
          channel, and left out market calls, live streams, Shorts, re-uploads and videos not about trading rules, judged from their titles.
          Dates of videos not analysed are approximate (YouTube lists them as &quot;5 years ago&quot;), so only the month is shown.
        </p>
        <div className="yc-tiles">
          <div className="yc-tile"><b>{num(m.channels)}</b><span>channels analysed</span></div>
          <div className="yc-tile"><b>{num(m.videos)}</b><span>videos analysed</span></div>
          <div className="yc-tile"><b>{num(m.strategies)}</b><span>strategies coded from them; {num(m.no_rule)} videos gave no testable rule, {num(m.repeats)} repeated one</span></div>
          <div className="yc-tile"><b>{num(m.uploads)}</b><span>uploads listed on {num(m.with_uploads_listed)} channels</span></div>
          <div className="yc-tile"><b>{num(m.listed_not_analysed)}</b><span>more channels listed, none analysed</span></div>
        </div>
        <div className="yc-reasons">
          {Object.entries(data.reasons).map(([r, label]) => (
            <div key={r} className="yc-reason"><b>{num(m.not_analysed[r] || 0)}</b> {label}</div>
          ))}
        </div>
        <div className="yc-controls">
          <input className="yc-q" placeholder="Search a channel, a video title or a strategy id" value={q} onChange={e => setQ(e.target.value)} aria-label="Search" />
          <select value={study} onChange={e => setStudy(e.target.value)} aria-label="Study">
            <option value="">Every study</option>
            {Object.entries(data.studies).map(([k, label]) => <option key={k} value={k}>{label}</option>)}
          </select>
          <select value={sort} onChange={e => setSort(e.target.value as typeof sort)} aria-label="Sort">
            <option value="analysed">Most videos analysed</option>
            <option value="untried">Most strategy titles not yet analysed</option>
            <option value="uploads">Most uploads</option>
            <option value="name">Name</option>
          </select>
          <span className="yc-dim">{num(shown.length)} of {num(data.channels.length)} channels. Open a channel to see its videos.</span>
        </div>
      </GlassPanel>

      <div className="yc-chans">
        {shown.map(c => <Channel key={key(c)} c={c} data={data} open={opened.has(key(c))} onToggle={open => toggle(c, open)} />)}
      </div>

      <GlassPanel title={`Channels listed but not analysed (${listedShown.length === data.listed.length ? data.listed.length : `${listedShown.length} of ${data.listed.length}`})`}
        note="uploads listed in the Trading Video Lab">
        <p className="yc-intro">
          Channels whose uploads were listed and classified, but none of whose videos has been read yet, with the reason. Where a video was
          picked but not read, it is listed under the reason.
        </p>
        <table className="yc-table">
          <thead><tr><th>Channel</th><th>Uploads</th><th>Strategy titles</th><th>Why none was analysed</th></tr></thead>
          <tbody>
            {listedShown.map(c => {
              const url = channelUrl(c);
              return (
                <tr key={c.id}>
                  <td>{url ? <a href={url} target="_blank" rel="noopener noreferrer">{c.name}</a> : c.name}</td>
                  <td className="yc-nowrap">{num(c.uploads)}</td>
                  <td className="yc-nowrap">{num(c.strategy_titles)}</td>
                  <td>
                    {c.reason}
                    {c.waiting.length > 0 && <ul className="yc-list">{c.waiting.map(u => <Upload key={u.v} u={u} />)}</ul>}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </GlassPanel>

      <style jsx global>{`
        .yc-intro { font-size: 13px; line-height: 1.6; color: var(--text-muted); margin: 0 0 12px; }
        .yc-tiles { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px; margin-bottom: 12px; }
        .yc-tile { border: 1px solid var(--panel-border); border-radius: 10px; padding: 10px 12px; }
        .yc-tile b { display: block; font-size: 20px; font-weight: 800; font-variant-numeric: tabular-nums; color: var(--text); }
        .yc-tile span { font-size: 12px; color: var(--text-muted); }
        .yc-reasons { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 6px 14px; margin-bottom: 12px; font-size: 12px;
          color: var(--text-muted); }
        .yc-reason b { font-variant-numeric: tabular-nums; color: var(--text); }
        .yc-controls { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
        .yc-q { min-width: 240px; flex: 1; padding: 6px 10px; border-radius: 8px; border: 1px solid var(--panel-border); background: transparent;
          color: inherit; font-size: 12.5px; }
        .yc-controls select { padding: 6px 8px; border-radius: 8px; border: 1px solid var(--panel-border); background: transparent; color: inherit; font-size: 12.5px; }
        .yc-chans { display: flex; flex-direction: column; gap: 8px; margin: 12px 0 16px; }
        .yc-ch { border: 1px solid var(--panel-border); border-radius: 10px; padding: 8px 12px; }
        .yc-ch > summary { cursor: pointer; display: flex; flex-wrap: wrap; gap: 6px 10px; align-items: center; list-style: none; }
        .yc-ch > summary::-webkit-details-marker { display: none; }
        .yc-ch > summary::before { content: "▸"; color: var(--text-muted); width: 10px; }
        .yc-ch[open] > summary::before { content: "▾"; }
        .yc-name { font-weight: 700; font-size: 14px; color: var(--text); }
        .yc-count { font-size: 12.5px; color: var(--text-muted); font-variant-numeric: tabular-nums; }
        .yc-body { margin-top: 8px; }
        .yc-line { font-size: 12.5px; margin-bottom: 6px; overflow-wrap: anywhere; }
        .yc-h { margin: 12px 0 4px; font-size: 12px; font-weight: 800; letter-spacing: 0.04em; text-transform: uppercase; color: var(--text-muted); }
        .yc-dim { color: var(--text-muted); font-size: 11.5px; }
        .yc-tag { font-size: 11px; padding: 1px 8px; border-radius: 999px; border: 1px solid var(--panel-border); color: var(--text-muted); margin-right: 4px;
          white-space: nowrap; display: inline-block; }
        .yc-tag.ok { border-color: var(--gain); color: var(--gain); }
        .yc-tag.warn { border-color: var(--warn-border); color: var(--warn); }
        .yc-table { width: 100%; border-collapse: collapse; font-size: 12px; }
        .yc-table th, .yc-table td { text-align: left; padding: 4px 6px; border-bottom: 1px solid var(--panel-border); vertical-align: top; overflow-wrap: anywhere; }
        .yc-nowrap { white-space: nowrap; font-variant-numeric: tabular-nums; }
        .yc-not { font-size: 12.5px; margin: 4px 0; }
        .yc-not summary { cursor: pointer; }
        .yc-list { margin: 4px 0 6px; padding-left: 18px; line-height: 1.55; font-size: 12px; }
        .yc-list li { margin-bottom: 2px; overflow-wrap: anywhere; }
        @media (max-width: 640px) { .yc-table th:nth-child(3), .yc-table td:nth-child(3) { display: none; } .yc-q { min-width: 0; } }
      `}</style>
    </>
  );
}
